nextflow_process {

    name "Test Process FOLDDISCO_INDEX"
    script "../main.nf"
    process "FOLDDISCO_INDEX"

    tag "modules"
    tag "modules_nfcore"
    tag "folddisco"
    tag "folddisco/index"

    test("proteomics - pdb") {

        config "./nextflow.config"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [
                        file(params.modules_testdata_base_path + 'proteomics/pdb/1tim.pdb', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'proteomics/pdb/8tim.pdb', checkIfExists: true)
                    ]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("proteomics - pdb - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    [
                        file(params.modules_testdata_base_path + 'proteomics/pdb/1tim.pdb', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'proteomics/pdb/8tim.pdb', checkIfExists: true)
                    ]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

process {
    withName: FOLDDISCO_INDEX {
        // folddisco preallocates its entire hash key space at startup regardless of input size;
        // the default hash type needs ~16.4 GB even for two 350 KB PDBs, OOM-killing the CI runner.
        // '-y pdb' hash algorithm drops that to ~1 GB - do not remove.
        ext.args = '-y pdb'
    }
}
